def generate_sequence(n):
    # Calculate the minimum length of the sequence
    min_length = (n * 4) // 3

    # Construct the sequence
    sequence = []
    for i in range(min_length):
        if i % 3 == 0:
            sequence.append('1')
        elif i % 3 == 1:
            sequence.append('3')
        else:
            sequence.append('7')

    # Ensure the sequence has exactly n subsequences of '1337'
    while True:
        count = 0
        for i in range(len(sequence) - 3):
            if ''.join(sequence[i:i+4]) == '1337':
                count += 1

        if count == n:
            break
        elif count < n:
            sequence.append('7')
        else:
            sequence.pop()

    return ''.join(sequence)

